1a3560"},"Treasury issues"));svg.appendChild(el("text",{x:e17x-30,y:margin.top+40,"text-anchor":"end","font-size":"7","font-weight":"700",fill:"#1a3560"},"60-day licence"));var lastX=xp(n-1),lastY=yp(vals[n-1]);var pillW=58,pillH=16;var pillX=lastX-pillW-6;var pillY=lastY-pillH/2;if(pillX<margin.left){pillX=lastX+6;}svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:3,fill:"#e8a825"}));svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700",fill:"#111111"},"$73.74"));var container=_cs.parentNode;container.appendChild(svg);})();</script></div><div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: NYMEX front-month settlement; U.S. Treasury OFAC General License X, June 22, 2026. &nbsp;|&nbsp; hdq.ca</div></div></div><p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">WTI''s 2.78 percent drop Monday was smaller than the eleven single-session moves exceeding 3 percent logged so far this month, even though the underlying catalyst, a dated Treasury licence, was more concrete than any headline behind those eleven.</p><h2>Gold Was Never an Iran Trade</h2><p>The Market desk''s session debrief on Friday found something easy to miss in the TSX''s 0.3 percent decline. Gold miners fell together, with Wheaton Precious Metals, Agnico Eagle and Barrick Gold all down in lockstep, while energy names split in opposite directions on company specific news. A sector moving together as a block is usually a single macro factor speaking through every name in it. Energy splitting apart is usually the opposite, the macro factor has stopped dominating and idiosyncratic stories have taken over.</p><p>The Economy desk named the macro factor without connecting it to gold. The Federal Reserve held its rate at 3.50 to 3.75 percent on June 17, but nine of 18 officials now project a 2026 hike, lifting the median projection to 3.8 percent from 3.4 percent in March. The US 10-year Treasury yield touched a one-week high of 4.489 percent Monday on that repricing. The Bank of Canada, by contrast, has now held five straight meetings at 2.25 percent, with Governor Tiff Macklem flagging a second consecutive quarterly contraction. Gold, a non-yielding asset, gets structurally less attractive every time real yields move in the direction they moved Monday, regardless of what Tehran does.</p><p>Gold''s path over the past four weeks tracks the climb in US Treasury yields far more closely than it tracks any single Iran headline, including this weekend''s Hormuz claim.</p><div class="hdq-chart"><div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;"><div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;"><span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">GOLD &#8212; COMEX FRONT MONTH (AUG)</span><span style="font-size:20px;font-weight:700;color:#111;">$4,214.20</span><span style="font-size:13px;color:#c0392b;">&#9660; -$31.70</span><span style="font-size:11px;color:#888;margin-left:auto;">DAILY &nbsp;|&nbsp; MAY 26&#8211;JUN 22, 2026</span></div><div style="padding:12px 14px 8px;"><script>(function(){var _cs=document.currentScript;function el(tag,attrs,txt){var e=document.createElementNS("http://www.w3.org/2000/svg",tag);if(attrs){for(var k in attrs){e.setAttribute(k,attrs[k]);}}if(txt!==undefined&&txt!==null){e.textContent=txt;}return e;}var dates=["5/26","5/27","5/28","5/29","6/1","6/2","6/3","6/4","6/5","6/8","6/9","6/11","6/12","6/15","6/16","6/18","6/19","6/22"];var vals=[4520,4480,4500,4450,4410,4430,4380,4340,4310,4280,4260,4150,4230,4300,4275,4260,4245.90,4214.20];var n=vals.length;var margin={left:62,right:24,top:18,bottom:46};var W=680,H=300;var PW=W-margin.left-margin.right;var PH=H-margin.top-margin.bottom;var minV=Math.min.apply(null,vals)-50;var maxV=Math.max.apply(null,vals)+50;function xp(i){return margin.left+i*(PW/(n-1));}function yp(v){return margin.top+PH*(maxV-v)/(maxV-minV);}var svg=document.createElementNS("http://www.w3.org/2000/svg","svg");svg.setAttribute("viewBox","0 0 680 300");svg.setAttribute("width","100%");for(var g=0;g<5;g++){var gy=margin.top+PH*g/4;svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:gy,y2:gy,stroke:"#ececec","stroke-width":"0.5"}));}svg.appendChild(el("line",{x1:margin.left,x2:margin.left,y1:margin.top,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));for(var g2=0;g2<5;g2++){var gv=maxV-(maxV-minV)*g2/4;var gy2=margin.top+PH*g2/4;svg.appendChild(el("text",{x:margin.left-6,y:gy2+3,"text-anchor":"end","font-size":"8.5",fill:"#aaa"},"$"+gv.toFixed(0)));}for(var i=0;i<n;i++){if(i%3===0||i===n-1){svg.appendChild(el("text",{x:xp(i),y:margin.top+PH+16,"text-anchor":"middle","font-size":"8",fill:"#999"},dates[i]));}}var refV=vals[0];var refY=yp(refV);svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:refY,y2:refY,stroke:"#2e7d32","stroke-dasharray":"3,3"}));var curV=vals[n-1];if(Math.abs(refV-curV)/curV>=0.03){svg.appendChild(el("text",{x:650,y:refY-3,"text-anchor":"end","font-size":"7.5",fill:"#2e7d32"},"MAY HIGH ZONE"));}var d="";for(var i=0;i<n;i++){d+=(i===0?"M":"L")+xp(i)+","+yp(vals[i])+" ";}svg.appendChild(el("path",{d:d,fill:"none",stroke:"#4a5568","stroke-width":"1.6"}));var e15x=xp(15);svg.appendChild(el("line",{x1:e15x,x2:e15x,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":"0.5","stroke-dasharray":"2,3"}));svg.appendChild(el("text",{x:e15x+3,y:margin.top+20,"font-size":"7","font-weight":"700",fill:"#1a3560"},"Fed holds,"));svg.appendChild(el("text",{x:e15x+3,y:margin.top+30,"font-size":"7","font-weight":"700",fill:"#1a3560"},"dot plot hawkish"));var lastX=xp(n-1),lastY=yp(vals[n-1]);var pillW=66,pillH=16;var pillX=lastX-pillW-6;var pillY=lastY-pillH/2;if(pillX<margin.left){pillX=lastX+6;}svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:3,fill:"#e8a825"}));svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700",fill:"#111111"},"$4,214"));var container=_cs.parentNode;container.appendChild(svg);})();</script></div><div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: COMEX gold futures settlement; Federal Reserve June 17 dot plot. &nbsp;|&nbsp; hdq.ca</div></div></div><p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Gold''s slide tracked the rise in US Treasury yields following the Fed''s June 17 dot plot more closely than it tracked any Iran headline that week. Real yields, not geopolitics, set the marginal price.</p><h2>The Number That Actually Matters Is Six Weeks Away</h2><p>The Tax and Wealth desk flagged something easy to read as a footnote this morning. The CRA confirmed Tuesday that the prescribed rate on family and employee loans stays at 3 percent for a fifth consecutive quarter, but the rate used for corporate pertinent loans and shareholder indebtedness rose to 6.3 percent for the third quarter, the first increase in any CRA administered rate since the easing cycle began in mid 2024. Both rates are set the same way: from the average yield on three month Government of Canada Treasury bills in the first month of the preceding quarter, rounded up. The number that sets the fourth quarter rate is July''s average, and July has not happened yet.</p><p>That is what makes Monday''s two stories matter together, not separately. Oil''s de-escalation is disinflationary and pulls short Canadian yields down. The Fed''s hawkish dot plot pulls them up through the cross border rate channel that has already weakened the Canadian dollar to 70.62 cents US. Both forces are now acting on the same handful of weeks that will determine whether the corporate prescribed rate''s first increase of the cycle is the start of a trend or a one quarter blip, and whether the family rate''s streak at 3 percent survives a sixth quarter.</p><p>An advisor with a client weighing a new prescribed rate loan does not need to wait for the CRA''s September announcement to know which way the wind is blowing. The signal is the path of short term Government of Canada Treasury bill yields between now and the end of July, and Monday gave that signal two genuinely separate inputs pulling in opposite directions on the same day. Treating today as a single Iran story, the mistake the Behavioural desk''s own research warns against, is the version of today that misses the one number actually worth tracking through the summer.</p>',
